package net.civeira.phylax.features.document.themeasset.application.policy;

import jakarta.enterprise.event.Observes;
import net.civeira.phylax.common.security.Actor;
import net.civeira.phylax.features.document.themeasset.application.visibility.ThemeAssetVisibilityCheck;

public class TenantAccesible {

  /**
   * @autogenerated VisibilityPolicyGenerator
   * @param filter
   */
  public void filterVisibles(@Observes ThemeAssetVisibilityCheck filter) {
    Actor actor = filter.getActor();
    if (!(actor.hasScope("platform:global_access"))) {
      filter.peek(fl -> fl.setThemeTenantAccesible(actor.getTenant()));
    }
  }
}
